(function() {
    var type_impls = Object.fromEntries([["umsh_ulcp_runtime",[["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Mac%3CP,+IDENTITIES,+PEERS,+CHANNELS,+ACKS,+TX,+FRAME,+DUP,+RN,+HN%3E\" class=\"impl\"><a href=\"#impl-Mac%3CP,+IDENTITIES,+PEERS,+CHANNELS,+ACKS,+TX,+FRAME,+DUP,+RN,+HN%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;P, const IDENTITIES: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const PEERS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const CHANNELS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const ACKS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const TX: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const FRAME: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const DUP: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const RN: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const HN: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>&gt; Mac&lt;P, IDENTITIES, PEERS, CHANNELS, ACKS, TX, FRAME, DUP, RN, HN&gt;<div class=\"where\">where\n    P: Platform,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.new\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.new\" class=\"fn\">new</a>(\n    radio: &lt;P as Platform&gt;::Radio,\n    crypto: CryptoEngine&lt;&lt;P as Platform&gt;::Aes, &lt;P as Platform&gt;::Sha&gt;,\n    clock: &lt;P as Platform&gt;::Clock,\n    rng: &lt;P as Platform&gt;::Rng,\n    counter_store: &lt;P as Platform&gt;::CounterStore,\n    repeater: RepeaterConfig,\n    operating_policy: OperatingPolicy,\n) -&gt; Mac&lt;P, IDENTITIES, PEERS, CHANNELS, ACKS, TX, FRAME, DUP, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Creates a MAC coordinator with the supplied radio, crypto, timing, and policy state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.counters\" class=\"method\"><h4 class=\"code-header\">pub const fn <a href=\"#method.counters\" class=\"fn\">counters</a>(&amp;self) -&gt; MacCounters</h4></section></summary><div class=\"docblock\"><p>Cumulative frame tallies since construction.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmitter_observations\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.transmitter_observations\" class=\"fn\">transmitter_observations</a>(&amp;self) -&gt; &amp;TransmitterObservations</h4></section></summary><div class=\"docblock\"><p>What has been heard from whom, most recently — the signal half of a\npeer-repeater listing.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.radio\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.radio\" class=\"fn\">radio</a>(&amp;self) -&gt; &amp;&lt;P as Platform&gt;::Radio</h4></section></summary><div class=\"docblock\"><p>Borrow the underlying radio.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.radio_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.radio_mut\" class=\"fn\">radio_mut</a>(&amp;mut self) -&gt; &amp;mut &lt;P as Platform&gt;::Radio</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the underlying radio.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.into_radio\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.into_radio\" class=\"fn\">into_radio</a>(self) -&gt; &lt;P as Platform&gt;::Radio</h4></section></summary><div class=\"docblock\"><p>Give up this coordinator and recover the radio underneath it.</p>\n<p>A host tool that borrows a device for the duration of one mesh\noperation gets its handle back this way, rather than dropping the\nattachment and paying for another.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.crypto\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.crypto\" class=\"fn\">crypto</a>(\n    &amp;self,\n) -&gt; &amp;CryptoEngine&lt;&lt;P as Platform&gt;::Aes, &lt;P as Platform&gt;::Sha&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the crypto engine.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clock\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.clock\" class=\"fn\">clock</a>(&amp;self) -&gt; &amp;&lt;P as Platform&gt;::Clock</h4></section></summary><div class=\"docblock\"><p>Borrow the monotonic clock.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.rng\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.rng\" class=\"fn\">rng</a>(&amp;self) -&gt; &amp;&lt;P as Platform&gt;::Rng</h4></section></summary><div class=\"docblock\"><p>Borrow the RNG.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.rng_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.rng_mut\" class=\"fn\">rng_mut</a>(&amp;mut self) -&gt; &amp;mut &lt;P as Platform&gt;::Rng</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the RNG.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.counter_store\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.counter_store\" class=\"fn\">counter_store</a>(&amp;self) -&gt; &amp;&lt;P as Platform&gt;::CounterStore</h4></section></summary><div class=\"docblock\"><p>Borrow the counter store.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.tx_queue\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.tx_queue\" class=\"fn\">tx_queue</a>(&amp;self) -&gt; &amp;TxQueue&lt;TX, FRAME&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the transmit queue.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.tx_queue_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.tx_queue_mut\" class=\"fn\">tx_queue_mut</a>(&amp;mut self) -&gt; &amp;mut TxQueue&lt;TX, FRAME&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the transmit queue.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.dup_cache\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.dup_cache\" class=\"fn\">dup_cache</a>(&amp;self) -&gt; &amp;DuplicateCache&lt;DUP&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the duplicate cache.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.peer_registry\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.peer_registry\" class=\"fn\">peer_registry</a>(&amp;self) -&gt; &amp;PeerRegistry&lt;PEERS&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.peer_registry_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.peer_registry_mut\" class=\"fn\">peer_registry_mut</a>(&amp;mut self) -&gt; &amp;mut PeerRegistry&lt;PEERS&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.channels\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.channels\" class=\"fn\">channels</a>(&amp;self) -&gt; &amp;ChannelTable&lt;CHANNELS, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the channel table.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.channels_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.channels_mut\" class=\"fn\">channels_mut</a>(&amp;mut self) -&gt; &amp;mut ChannelTable&lt;CHANNELS, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the channel table.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_config\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.repeater_config\" class=\"fn\">repeater_config</a>(&amp;self) -&gt; &amp;RepeaterConfig</h4></section></summary><div class=\"docblock\"><p>Borrow repeater configuration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_config_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.repeater_config_mut\" class=\"fn\">repeater_config_mut</a>(&amp;mut self) -&gt; &amp;mut RepeaterConfig</h4></section></summary><div class=\"docblock\"><p>Mutably borrow repeater configuration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.operating_policy\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.operating_policy\" class=\"fn\">operating_policy</a>(&amp;self) -&gt; &amp;OperatingPolicy</h4></section></summary><div class=\"docblock\"><p>Borrow the local operating policy.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.operating_policy_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.operating_policy_mut\" class=\"fn\">operating_policy_mut</a>(&amp;mut self) -&gt; &amp;mut OperatingPolicy</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the local operating policy.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.auto_register_full_key_peers\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.auto_register_full_key_peers\" class=\"fn\">auto_register_full_key_peers</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Return whether inbound secure packets carrying a full source key may auto-register peers.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_auto_register_full_key_peers\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.set_auto_register_full_key_peers\" class=\"fn\">set_auto_register_full_key_peers</a>(&amp;mut self, enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>)</h4></section></summary><div class=\"docblock\"><p>Enable or disable inbound full-key peer auto-registration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_identity\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.add_identity\" class=\"fn\">add_identity</a>(\n    &amp;mut self,\n    identity: &lt;P as Platform&gt;::Identity,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;LocalIdentityId, CapacityError&gt;</h4></section></summary><div class=\"docblock\"><p>Register one long-term local identity.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.load_persisted_counter\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.load_persisted_counter\" class=\"fn\">load_persisted_counter</a>(\n    &amp;mut self,\n    id: LocalIdentityId,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, CounterPersistenceError&lt;&lt;&lt;P as Platform&gt;::CounterStore as CounterStore&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Load the persisted frame-counter boundary for <code>id</code> from the counter store.</p>\n<h5 id=\"flash-wear-invariant\"><a class=\"doc-anchor\" href=\"#flash-wear-invariant\">§</a>Flash-wear invariant</h5>\n<p>This method must remain read-only. In particular, booting or repeatedly\nrebooting without transmitting must never write a new reservation and\nwear out embedded flash. The first authenticated send schedules the\nfuture reservation; the MAC driver services that pending write because\nactual transmission has made persistence necessary.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.service_counter_persistence\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.service_counter_persistence\" class=\"fn\">service_counter_persistence</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, &lt;&lt;P as Platform&gt;::CounterStore as CounterStore&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Persist all currently scheduled frame-counter reservations.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.load_all_persisted_rx_counters\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.load_all_persisted_rx_counters\" class=\"fn\">load_all_persisted_rx_counters</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, &lt;&lt;P as Platform&gt;::CounterStore as CounterStore&gt;::Error&gt;</h4></section></summary><div class=\"docblock\"><p>Load persisted RX frame-counter boundaries for all registered peers and\nstore them in [<code>PeerInfo::initial_rx_counter</code>].</p>\n<p>Call this once at boot after registering all known peers. When pairwise\nkeys are first derived for each peer, the replay window is initialized\nto the loaded boundary so frames replayed from before the reboot are\nrejected.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.register_ephemeral\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.register_ephemeral\" class=\"fn\">register_ephemeral</a>(\n    &amp;mut self,\n    parent: LocalIdentityId,\n    identity: SoftwareIdentity,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;LocalIdentityId, CapacityError&gt;</h4></section></summary><div class=\"docblock\"><p>Register an ephemeral software identity linked to <code>parent</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_ephemeral\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.remove_ephemeral\" class=\"fn\">remove_ephemeral</a>(&amp;mut self, id: LocalIdentityId) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Remove an ephemeral identity slot if one exists at <code>id</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.identity\" class=\"fn\">identity</a>(\n    &amp;self,\n    id: LocalIdentityId,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;IdentitySlot&lt;&lt;P as Platform&gt;::Identity, PEERS, ACKS, FRAME&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow an identity slot by identifier.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity_mut\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.identity_mut\" class=\"fn\">identity_mut</a>(\n    &amp;mut self,\n    id: LocalIdentityId,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;mut IdentitySlot&lt;&lt;P as Platform&gt;::Identity, PEERS, ACKS, FRAME&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow an identity slot by identifier.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_peer\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.add_peer\" class=\"fn\">add_peer</a>(&amp;mut self, key: PublicKey) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;PeerId, AddPeerError&gt;</h4></section></summary><div class=\"docblock\"><p>Registers or refreshes a known remote peer in the shared registry.</p>\n<p>When the <code>software-crypto</code> feature is enabled, the supplied public key\nis validated as a well-formed Ed25519 compressed point on the curve.\nMalformed keys are rejected with [<code>AddPeerError::InvalidPublicKey</code>]\nbefore they can pollute the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_peer\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.remove_peer\" class=\"fn\">remove_peer</a>(&amp;mut self, key: &amp;PublicKey) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Removes a registered peer and every piece of per-peer transport state:\npairwise crypto, replay windows, pending counter resyncs, and any\ndeferred inbound frame. Returns whether the peer was registered.</p>\n<p>The peer registry is dense, so removal moves the last entry into the\nfreed slot; state keyed by the moved peer’s old identifier is re-keyed\nhere. Persisted RX counter boundaries are deliberately retained: if\nthe peer is re-added later, replay protection resumes from the stored\nboundary instead of accepting replays from before the removal.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_channel\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.add_channel\" class=\"fn\">add_channel</a>(&amp;mut self, key: ChannelKey) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, CapacityError&gt;</h4></section></summary><div class=\"docblock\"><p>Adds or updates a shared channel and derives its multicast keys.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_channel\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.remove_channel\" class=\"fn\">remove_channel</a>(&amp;mut self, key: &amp;ChannelKey) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Removes a previously added channel by its exact key, discarding\nthe channel’s replay state with it (re-adding the key later\nstarts at first contact). Returns whether a channel was removed.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_named_channel\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.add_named_channel\" class=\"fn\">add_named_channel</a>(&amp;mut self, name: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, AddChannelError&gt;</h4></section></summary><div class=\"docblock\"><p>Adds or updates a named channel using the coordinator’s channel-key derivation.</p>\n<p>The name is canonicalized (ASCII lowercase fold) before derivation, so\n<code>Public</code> and <code>public</code> register the same channel.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity_count\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.identity_count\" class=\"fn\">identity_count</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a></h4></section></summary><div class=\"docblock\"><p>Return the number of occupied identity slots.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.install_pairwise_keys_advanced\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.install_pairwise_keys_advanced\" class=\"fn\">install_pairwise_keys_advanced</a>(\n    &amp;mut self,\n    identity_id: LocalIdentityId,\n    peer_id: PeerId,\n    pairwise_keys: PairwiseKeys,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;PeerCryptoState&gt;, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Installs pairwise transport keys for one local identity and remote peer.</p>\n<h5 id=\"safety-logical\"><a class=\"doc-anchor\" href=\"#safety-logical\">§</a>Safety (logical)</h5>\n<p>Installing wrong keys will silently corrupt the session. This method\nis deliberately gated behind the <code>unsafe-advanced</code> feature. Prefer\ngoing through the node-layer PFS session manager instead.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_broadcast\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_broadcast\" class=\"fn\">queue_broadcast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;SendReceipt, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a broadcast frame for transmission.</p>\n<p>Note: the <code>encrypted</code>, <code>ack_requested</code>, and <code>salt</code> flags on <code>options</code>\nare silently forced to <code>false</code> because broadcasts cannot carry any of\nthem on the wire.</p>\n<p>TODO: this sanitization is silent — a caller that explicitly set\n<code>ack_requested = true</code> for a broadcast will get a successful\n<code>SendReceipt</code> and never learn the flag was dropped. Surface this as a\ndebug-level event (or split <code>SendOptions</code> into kind-specific\nbuilders) so the loss is observable.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_broadcast\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.send_broadcast\" class=\"fn\">send_broadcast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;SendReceipt, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a broadcast frame for transmission.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_multicast\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_multicast\" class=\"fn\">queue_multicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;SendReceipt, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a multicast frame using the configured channel keys.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_multicast\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.send_multicast\" class=\"fn\">send_multicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;SendReceipt, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a multicast frame for transmission.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_mac_ack_for_peer\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_mac_ack_for_peer\" class=\"fn\">queue_mac_ack_for_peer</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    peer_id: PeerId,\n    ack_trailer: [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>],\n    trace_route: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a MAC ACK frame, using any cached route to <code>peer_id</code> when available.</p>\n<p><code>trace_route</code> mirrors the acknowledged frame: a sender that attached a\ntrace route was discovering a path, and the trace it collected only\ntaught <em>us</em> the way back. The matching trace on this ack is what closes\nthe other direction, and is the only thing an ack-only exchange gives\nthe sender to learn a route from.</p>\n<p>It is honored only when the route attached below gives this ack some\nway to be repeated. An ack going back to a peer we hear directly\ncarries neither a flood budget nor a source route, so no repeater may\ntouch it and the trace would arrive as empty as it left. The sender\nreads the direct link off the ack’s own shape instead — see\n[<code>Coordinator::learn_route_for_peer</code>].</p>\n<p>An ack that does ride through repeaters is tracked like any other\nrepeat-confirmed send: silence where the repeat should be means the\nfirst hop never got it, and the retry ladder retransmits. The ladder\nends in a silent abandon — the sender’s own data retries are the\nbackstop; this just spares them in the common case.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_mac_ack\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_mac_ack\" class=\"fn\">queue_mac_ack</a>(&amp;mut self, ack_trailer: [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>]) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues an immediate direct MAC ACK frame.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_unicast\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_unicast\" class=\"fn\">queue_unicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    peer: &amp;PublicKey,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;SendReceipt&gt;, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a unicast frame and optional pending-ACK state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_unicast\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.send_unicast\" class=\"fn\">send_unicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    peer: &amp;PublicKey,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;SendReceipt&gt;, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a unicast frame for transmission, deriving secure peer state on first use.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_blind_unicast\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.queue_blind_unicast\" class=\"fn\">queue_blind_unicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    peer: &amp;PublicKey,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;SendReceipt&gt;, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a blind-unicast frame and optional pending-ACK state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_blind_unicast\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.send_blind_unicast\" class=\"fn\">send_blind_unicast</a>(\n    &amp;mut self,\n    from: LocalIdentityId,\n    peer: &amp;PublicKey,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;SendOptions,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;SendReceipt&gt;, SendError&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a blind-unicast frame for transmission, deriving secure peer state on first use.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmit_next\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.transmit_next\" class=\"fn\">transmit_next</a>(\n    &amp;mut self,\n    on_event: &amp;mut impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;SendReceipt&gt;, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Transmit the next eligible queued frame, if any.</p>\n<p>While a post-transmit forwarding listen window is active, only immediate MAC\nACK traffic is permitted to bypass the listen state. Forwarded sends arm a new\nlisten window after the radio transmit completes. Non-immediate traffic honors\nqueued CAD backoff state and gives up after the configured maximum number of\nCAD attempts.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.drain_tx_queue\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.drain_tx_queue\" class=\"fn\">drain_tx_queue</a>(\n    &amp;mut self,\n    on_event: &amp;mut impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Keep transmitting until the queue is empty.</p>\n<p>Progress stops when CAD keeps reporting busy, when a post-transmit listen window blocks\nnormal traffic, or when the queue is otherwise unable to shrink further in the current cycle.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_cycle\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.poll_cycle\" class=\"fn\">poll_cycle</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Runs one coordinator cycle over the current MAC state.</p>\n<p>The cycle performs four ordered phases:</p>\n<ol>\n<li>Drain any queued transmit work.</li>\n<li>Receive and process at most one inbound frame.</li>\n<li>Drain any immediate ACK generated during receive handling.</li>\n<li>Service pending ACK timers and emit timeout events.</li>\n</ol>\n<p>The callback may be invoked zero or more times depending on what the\nreceive and timeout phases accept or resolve.\nService one MAC coordinator cycle.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.earliest_deadline_ms\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.earliest_deadline_ms\" class=\"fn\">earliest_deadline_ms</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u64.html\">u64</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Compute the earliest deadline across all coordinator timers.</p>\n<p>Returns <code>None</code> when there are no pending timers.  The returned value\ncovers pending ACK deadlines (both <code>ack_deadline_ms</code> and forwarding\n<code>confirm_deadline_ms</code>), the post-transmit listen window, and deferred\ntransmit-queue entries.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.next_event\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.next_event\" class=\"fn\">next_event</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Run the coordinator’s event loop until at least one event is delivered\nor a timer-driven action (retransmit, timeout) is processed.</p>\n<p>Unlike <a href=\"Self::poll_cycle\"><code>poll_cycle</code></a>, this method properly awaits the\nradio and timer deadlines instead of returning immediately when nothing\nis ready.  Callers can use <code>tokio::select!</code> (or equivalent) to multiplex\nuser input alongside MAC events:</p>\n\n<div class=\"example-wrap ignore\"><a href=\"#\" class=\"tooltip\" title=\"This example is not tested\">ⓘ</a><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">loop </span>{\n    <span class=\"macro\">tokio::select!</span> {\n        line = stdin.next_line() =&gt; { <span class=\"comment\">/* handle input */ </span>}\n        result = mac.next_event(|id, event| { <span class=\"comment\">/* handle event */ </span>}) =&gt; {\n            result<span class=\"question-mark\">?</span>;\n        }\n    }\n}</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_wait_for_wake\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.poll_wait_for_wake\" class=\"fn\">poll_wait_for_wake</a>(\n    &amp;mut self,\n    cx: &amp;mut <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/core/task/wake/struct.Context.html\" title=\"struct core::task::wake::Context\">Context</a>&lt;'_&gt;,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/task/poll/enum.Poll.html\" title=\"enum core::task::poll::Poll\">Poll</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;WakeReason, &lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Register radio/timer wakers and report what has become ready.</p>\n<p>This is Phase 2 of <a href=\"Self::next_event\"><code>next_event</code></a> exposed as a sync\npoll method so that callers sharing the coordinator through an\n<code>AsyncRefCell</code> can release the exclusive borrow between polls. The\ncaller-provided <code>buf</code> is populated with the received frame when the\nreturn value is [<code>WakeReason::Received</code>].</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.process_wake_reason\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.process_wake_reason\" class=\"fn\">process_wake_reason</a>(\n    &amp;mut self,\n    reason: WakeReason,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Run Phases 3-5 after <a href=\"Self::poll_wait_for_wake\"><code>poll_wait_for_wake</code></a>\nhas reported a wake reason: process the received frame (if any),\ndrain immediate ACKs, and service pending ACK timeouts.</p>\n<h5 id=\"precondition\"><a class=\"doc-anchor\" href=\"#precondition\">§</a>Precondition</h5>\n<p>When <code>reason</code> is [<code>WakeReason::Received</code>], <code>buf</code> <strong>must</strong> be the same\nbuffer — containing the same bytes — that was passed to the matching\n<a href=\"Self::poll_wait_for_wake\"><code>poll_wait_for_wake</code></a> call. The received\nframe bytes live in <code>buf[..rx.len]</code>; <code>reason</code> only carries the\naccompanying metadata (<code>RxInfo</code>). Passing a different or reinitialized\nbuffer will cause the received frame to be silently discarded and the\ncontents of <code>buf</code> to be misinterpreted as a MAC frame.</p>\n<p>This precondition only matters when using the split-phase API for\n<a href=\"umsh_sync::AsyncRefCell\"><code>AsyncRefCell</code></a> sharing. When driving the\ncoordinator through <a href=\"Self::next_event\"><code>next_event</code></a> the buffer is a\nlocal stack variable and the pairing is guaranteed automatically.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.run\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.run\" class=\"fn\">run</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Drive the coordinator forever, invoking <code>on_event</code> for each delivered event.</p>\n<p>This is the preferred long-lived run loop for standalone MAC-driven tasks such as\nrepeaters or dedicated radio services. Unlike manually calling\n<a href=\"Self::poll_cycle\"><code>poll_cycle</code></a> in a loop, <code>run</code> keeps the wake/sleep policy inside\nthe coordinator by delegating to <a href=\"Self::next_event\"><code>next_event</code></a>, which already\nwaits for radio activity and protocol deadlines.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.run_quiet\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.run_quiet\" class=\"fn\">run_quiet</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Drive the coordinator forever while ignoring emitted events.</p>\n<p>Useful for standalone repeaters or bridge tasks that do not need to observe inbound\ndeliveries directly but still need the coordinator to service forwarding, ACKs, and\nretransmissions without an app-owned polling loop.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.process_received_frame\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.process_received_frame\" class=\"fn\">process_received_frame</a>(\n    &amp;mut self,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n    frame_len: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>,\n    rx: &amp;RxInfo,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Process a received frame, dispatching events through <code>on_event</code>.</p>\n<p>This is the shared implementation used by both <a href=\"Self::receive_one\"><code>receive_one</code></a>\nand <a href=\"Self::next_event\"><code>next_event</code></a>.  Returns <code>true</code> when the frame\nproduced at least one event or side-effect.</p>\n<p>Every reception passes through here exactly once, which is what\nmakes it the place to tally them: the <code>rx_frames</code>/<code>rx_accepted</code>\npair counts one radio reception and whether anything came of it.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.receive_one\" class=\"method\"><h4 class=\"code-header\">pub async fn <a href=\"#method.receive_one\" class=\"fn\">receive_one</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, MacError&lt;&lt;&lt;P as Platform&gt;::Radio as Radio&gt;::Error&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Non-blocking receive: polls the radio once and processes a frame if available.</p>\n<p>This is the legacy non-blocking API used by <a href=\"Self::poll_cycle\"><code>poll_cycle</code></a>.\nFor new code, prefer <a href=\"Self::next_event\"><code>next_event</code></a> which properly awaits\nthe radio and timer deadlines.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.complete_ack\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.complete_ack\" class=\"fn\">complete_ack</a>(\n    &amp;mut self,\n    peer: &amp;PublicKey,\n    ack_trailer: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;(LocalIdentityId, SendReceipt)&gt;</h4></section></summary><div class=\"docblock\"><p>Mark a pending receipt as acknowledged and emit an event through <code>on_event</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.service_pending_ack_timeouts\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.service_pending_ack_timeouts\" class=\"fn\">service_pending_ack_timeouts</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(LocalIdentityId, MacEventRef&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, CapacityError&gt;</h4></section></summary><div class=\"docblock\"><p>Expire or retry pending ACK state based on <code>now_ms</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.cancel_pending_ack\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.cancel_pending_ack\" class=\"fn\">cancel_pending_ack</a>(\n    &amp;mut self,\n    identity_id: LocalIdentityId,\n    receipt: SendReceipt,\n) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Cancel a pending ACK-requested send, stopping retransmissions.</p>\n<p>Removes the pending ACK entry for the given identity slot and receipt,\nand removes any matching entry from the transmit queue. Returns <code>true</code>\nif a pending ACK was found and removed.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.ensure_transient_peer\" class=\"method\"><h4 class=\"code-header\">pub fn <a href=\"#method.ensure_transient_peer\" class=\"fn\">ensure_transient_peer</a>(\n    &amp;mut self,\n    key: &amp;PublicKey,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;PeerId, AddPeerError&gt;</h4></section></summary><div class=\"docblock\"><p>Ensure <code>key</code> is registered at least transiently, returning its slot.</p>\n<p>A known peer is returned as-is; an unknown one is auto-registered\nexactly like a full-source sender would be — unpinned and\nLRU-evictable, never promoted. This is the node layer’s hook for\nanswering a stranger (an Identity Request reply, say) whose frame\narrived on a path that does not auto-register its source, such as a\nbroadcast. Deliberately not gated on\n<a href=\"Self::auto_register_full_key_peers\"><code>auto_register_full_key_peers</code></a>:\nthe caller is making an explicit per-peer decision, not opting into\nregistering every full-source sender.</p>\n</div></details></div></details>",0,"umsh_ulcp_runtime::device_node::DeviceNodeMac"]]],["umshctl",[["<details class=\"toggle implementors-toggle\" open><summary><section id=\"impl-Mac%3CP,+IDENTITIES,+PEERS,+CHANNELS,+ACKS,+TX,+FRAME,+DUP,+RN,+HN%3E\" class=\"impl\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#942-953\">Source</a><a href=\"#impl-Mac%3CP,+IDENTITIES,+PEERS,+CHANNELS,+ACKS,+TX,+FRAME,+DUP,+RN,+HN%3E\" class=\"anchor\">§</a><h3 class=\"code-header\">impl&lt;P, const IDENTITIES: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const PEERS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const CHANNELS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const ACKS: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const TX: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const FRAME: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const DUP: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const RN: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, const HN: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>&gt; <a class=\"struct\" href=\"umsh_mac/coordinator/struct.Mac.html\" title=\"struct umsh_mac::coordinator::Mac\">Mac</a>&lt;P, IDENTITIES, PEERS, CHANNELS, ACKS, TX, FRAME, DUP, RN, HN&gt;<div class=\"where\">where\n    P: <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>,</div></h3></section></summary><div class=\"impl-items\"><details class=\"toggle method-toggle\" open><summary><section id=\"method.new\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#956-964\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.new\" class=\"fn\">new</a>(\n    radio: &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a>,\n    crypto: CryptoEngine&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Aes\" title=\"type umsh_mac::Platform::Aes\">Aes</a>, &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Sha\" title=\"type umsh_mac::Platform::Sha\">Sha</a>&gt;,\n    clock: &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Clock\" title=\"type umsh_mac::Platform::Clock\">Clock</a>,\n    rng: &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Rng\" title=\"type umsh_mac::Platform::Rng\">Rng</a>,\n    counter_store: &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.CounterStore\" title=\"type umsh_mac::Platform::CounterStore\">CounterStore</a>,\n    repeater: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.RepeaterConfig.html\" title=\"struct umsh_mac::coordinator::RepeaterConfig\">RepeaterConfig</a>,\n    operating_policy: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.OperatingPolicy.html\" title=\"struct umsh_mac::coordinator::OperatingPolicy\">OperatingPolicy</a>,\n) -&gt; <a class=\"struct\" href=\"umsh_mac/coordinator/struct.Mac.html\" title=\"struct umsh_mac::coordinator::Mac\">Mac</a>&lt;P, IDENTITIES, PEERS, CHANNELS, ACKS, TX, FRAME, DUP, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Creates a MAC coordinator with the supplied radio, crypto, timing, and policy state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.counters\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#988\">Source</a><h4 class=\"code-header\">pub const fn <a href=\"#method.counters\" class=\"fn\">counters</a>(&amp;self) -&gt; <a class=\"struct\" href=\"umsh_mac/coordinator/struct.MacCounters.html\" title=\"struct umsh_mac::coordinator::MacCounters\">MacCounters</a></h4></section></summary><div class=\"docblock\"><p>Cumulative frame tallies since construction.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmitter_observations\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#994\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.transmitter_observations\" class=\"fn\">transmitter_observations</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/observations/struct.TransmitterObservations.html\" title=\"struct umsh_mac::observations::TransmitterObservations\">TransmitterObservations</a></h4></section></summary><div class=\"docblock\"><p>What has been heard from whom, most recently — the signal half of a\npeer-repeater listing.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.radio\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#999\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.radio\" class=\"fn\">radio</a>(&amp;self) -&gt; &amp;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a></h4></section></summary><div class=\"docblock\"><p>Borrow the underlying radio.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.radio_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1004\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.radio_mut\" class=\"fn\">radio_mut</a>(&amp;mut self) -&gt; &amp;mut &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a></h4></section></summary><div class=\"docblock\"><p>Mutably borrow the underlying radio.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.into_radio\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1013\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.into_radio\" class=\"fn\">into_radio</a>(self) -&gt; &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a></h4></section></summary><div class=\"docblock\"><p>Give up this coordinator and recover the radio underneath it.</p>\n<p>A host tool that borrows a device for the duration of one mesh\noperation gets its handle back this way, rather than dropping the\nattachment and paying for another.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.crypto\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1018\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.crypto\" class=\"fn\">crypto</a>(\n    &amp;self,\n) -&gt; &amp;CryptoEngine&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Aes\" title=\"type umsh_mac::Platform::Aes\">Aes</a>, &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Sha\" title=\"type umsh_mac::Platform::Sha\">Sha</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the crypto engine.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.clock\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1023\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.clock\" class=\"fn\">clock</a>(&amp;self) -&gt; &amp;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Clock\" title=\"type umsh_mac::Platform::Clock\">Clock</a></h4></section></summary><div class=\"docblock\"><p>Borrow the monotonic clock.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.rng\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1028\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.rng\" class=\"fn\">rng</a>(&amp;self) -&gt; &amp;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Rng\" title=\"type umsh_mac::Platform::Rng\">Rng</a></h4></section></summary><div class=\"docblock\"><p>Borrow the RNG.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.rng_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1033\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.rng_mut\" class=\"fn\">rng_mut</a>(&amp;mut self) -&gt; &amp;mut &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Rng\" title=\"type umsh_mac::Platform::Rng\">Rng</a></h4></section></summary><div class=\"docblock\"><p>Mutably borrow the RNG.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.counter_store\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1038\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.counter_store\" class=\"fn\">counter_store</a>(&amp;self) -&gt; &amp;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.CounterStore\" title=\"type umsh_mac::Platform::CounterStore\">CounterStore</a></h4></section></summary><div class=\"docblock\"><p>Borrow the counter store.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.tx_queue\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1042\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.tx_queue\" class=\"fn\">tx_queue</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.TxQueue.html\" title=\"struct umsh_mac::send::TxQueue\">TxQueue</a>&lt;TX, FRAME&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the transmit queue.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.tx_queue_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1046\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.tx_queue_mut\" class=\"fn\">tx_queue_mut</a>(&amp;mut self) -&gt; &amp;mut <a class=\"struct\" href=\"umsh_mac/send/struct.TxQueue.html\" title=\"struct umsh_mac::send::TxQueue\">TxQueue</a>&lt;TX, FRAME&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the transmit queue.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.dup_cache\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1050\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.dup_cache\" class=\"fn\">dup_cache</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/cache/struct.DuplicateCache.html\" title=\"struct umsh_mac::cache::DuplicateCache\">DuplicateCache</a>&lt;DUP&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the duplicate cache.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.peer_registry\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1054\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.peer_registry\" class=\"fn\">peer_registry</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/peers/struct.PeerRegistry.html\" title=\"struct umsh_mac::peers::PeerRegistry\">PeerRegistry</a>&lt;PEERS&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.peer_registry_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1058\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.peer_registry_mut\" class=\"fn\">peer_registry_mut</a>(&amp;mut self) -&gt; &amp;mut <a class=\"struct\" href=\"umsh_mac/peers/struct.PeerRegistry.html\" title=\"struct umsh_mac::peers::PeerRegistry\">PeerRegistry</a>&lt;PEERS&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.channels\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1062\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.channels\" class=\"fn\">channels</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/peers/struct.ChannelTable.html\" title=\"struct umsh_mac::peers::ChannelTable\">ChannelTable</a>&lt;CHANNELS, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow the channel table.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.channels_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1066\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.channels_mut\" class=\"fn\">channels_mut</a>(&amp;mut self) -&gt; &amp;mut <a class=\"struct\" href=\"umsh_mac/peers/struct.ChannelTable.html\" title=\"struct umsh_mac::peers::ChannelTable\">ChannelTable</a>&lt;CHANNELS, RN, HN&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow the channel table.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_config\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1070\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.repeater_config\" class=\"fn\">repeater_config</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/coordinator/struct.RepeaterConfig.html\" title=\"struct umsh_mac::coordinator::RepeaterConfig\">RepeaterConfig</a></h4></section></summary><div class=\"docblock\"><p>Borrow repeater configuration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.repeater_config_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1074\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.repeater_config_mut\" class=\"fn\">repeater_config_mut</a>(&amp;mut self) -&gt; &amp;mut <a class=\"struct\" href=\"umsh_mac/coordinator/struct.RepeaterConfig.html\" title=\"struct umsh_mac::coordinator::RepeaterConfig\">RepeaterConfig</a></h4></section></summary><div class=\"docblock\"><p>Mutably borrow repeater configuration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.operating_policy\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1078\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.operating_policy\" class=\"fn\">operating_policy</a>(&amp;self) -&gt; &amp;<a class=\"struct\" href=\"umsh_mac/coordinator/struct.OperatingPolicy.html\" title=\"struct umsh_mac::coordinator::OperatingPolicy\">OperatingPolicy</a></h4></section></summary><div class=\"docblock\"><p>Borrow the local operating policy.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.operating_policy_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1082\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.operating_policy_mut\" class=\"fn\">operating_policy_mut</a>(&amp;mut self) -&gt; &amp;mut <a class=\"struct\" href=\"umsh_mac/coordinator/struct.OperatingPolicy.html\" title=\"struct umsh_mac::coordinator::OperatingPolicy\">OperatingPolicy</a></h4></section></summary><div class=\"docblock\"><p>Mutably borrow the local operating policy.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.auto_register_full_key_peers\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1087\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.auto_register_full_key_peers\" class=\"fn\">auto_register_full_key_peers</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Return whether inbound secure packets carrying a full source key may auto-register peers.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.set_auto_register_full_key_peers\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1092\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.set_auto_register_full_key_peers\" class=\"fn\">set_auto_register_full_key_peers</a>(&amp;mut self, enabled: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>)</h4></section></summary><div class=\"docblock\"><p>Enable or disable inbound full-key peer auto-registration.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_identity\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1097-1100\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.add_identity\" class=\"fn\">add_identity</a>(\n    &amp;mut self,\n    identity: &lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Identity\" title=\"type umsh_mac::Platform::Identity\">Identity</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"struct\" href=\"umsh_mac/struct.CapacityError.html\" title=\"struct umsh_mac::CapacityError\">CapacityError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Register one long-term local identity.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.load_persisted_counter\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1113-1116\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.load_persisted_counter\" class=\"fn\">load_persisted_counter</a>(\n    &amp;mut self,\n    id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u32.html\">u32</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.CounterPersistenceError.html\" title=\"enum umsh_mac::coordinator::CounterPersistenceError\">CounterPersistenceError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.CounterStore\" title=\"type umsh_mac::Platform::CounterStore\">CounterStore</a> as <a class=\"trait\" href=\"umsh_hal/trait.CounterStore.html\" title=\"trait umsh_hal::CounterStore\">CounterStore</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.CounterStore.html#associatedtype.Error\" title=\"type umsh_hal::CounterStore::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Load the persisted frame-counter boundary for <code>id</code> from the counter store.</p>\n<h5 id=\"flash-wear-invariant\"><a class=\"doc-anchor\" href=\"#flash-wear-invariant\">§</a>Flash-wear invariant</h5>\n<p>This method must remain read-only. In particular, booting or repeatedly\nrebooting without transmitting must never write a new reservation and\nwear out embedded flash. The first authenticated send schedules the\nfuture reservation; the MAC driver services that pending write because\nactual transmission has made persistence necessary.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.service_counter_persistence\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1150-1152\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.service_counter_persistence\" class=\"fn\">service_counter_persistence</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, &lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.CounterStore\" title=\"type umsh_mac::Platform::CounterStore\">CounterStore</a> as <a class=\"trait\" href=\"umsh_hal/trait.CounterStore.html\" title=\"trait umsh_hal::CounterStore\">CounterStore</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.CounterStore.html#associatedtype.Error\" title=\"type umsh_hal::CounterStore::Error\">Error</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Persist all currently scheduled frame-counter reservations.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.load_all_persisted_rx_counters\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1254-1256\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.load_all_persisted_rx_counters\" class=\"fn\">load_all_persisted_rx_counters</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>, &lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.CounterStore\" title=\"type umsh_mac::Platform::CounterStore\">CounterStore</a> as <a class=\"trait\" href=\"umsh_hal/trait.CounterStore.html\" title=\"trait umsh_hal::CounterStore\">CounterStore</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.CounterStore.html#associatedtype.Error\" title=\"type umsh_hal::CounterStore::Error\">Error</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Load persisted RX frame-counter boundaries for all registered peers and\nstore them in [<code>PeerInfo::initial_rx_counter</code>].</p>\n<p>Call this once at boot after registering all known peers. When pairwise\nkeys are first derived for each peer, the replay window is initialized\nto the loaded boundary so frames replayed from before the reboot are\nrejected.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.register_ephemeral\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1279-1283\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.register_ephemeral\" class=\"fn\">register_ephemeral</a>(\n    &amp;mut self,\n    parent: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    identity: SoftwareIdentity,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"struct\" href=\"umsh_mac/struct.CapacityError.html\" title=\"struct umsh_mac::CapacityError\">CapacityError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Register an ephemeral software identity linked to <code>parent</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_ephemeral\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1289\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.remove_ephemeral\" class=\"fn\">remove_ephemeral</a>(&amp;mut self, id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Remove an ephemeral identity slot if one exists at <code>id</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1304-1307\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.identity\" class=\"fn\">identity</a>(\n    &amp;self,\n    id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;<a class=\"struct\" href=\"umsh_mac/coordinator/struct.IdentitySlot.html\" title=\"struct umsh_mac::coordinator::IdentitySlot\">IdentitySlot</a>&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Identity\" title=\"type umsh_mac::Platform::Identity\">Identity</a>, PEERS, ACKS, FRAME&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Borrow an identity slot by identifier.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity_mut\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1312-1315\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.identity_mut\" class=\"fn\">identity_mut</a>(\n    &amp;mut self,\n    id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;&amp;mut <a class=\"struct\" href=\"umsh_mac/coordinator/struct.IdentitySlot.html\" title=\"struct umsh_mac::coordinator::IdentitySlot\">IdentitySlot</a>&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Identity\" title=\"type umsh_mac::Platform::Identity\">Identity</a>, PEERS, ACKS, FRAME&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Mutably borrow an identity slot by identifier.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_peer\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1325\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.add_peer\" class=\"fn\">add_peer</a>(&amp;mut self, key: PublicKey) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/peers/struct.PeerId.html\" title=\"struct umsh_mac::peers::PeerId\">PeerId</a>, <a class=\"enum\" href=\"umsh_mac/enum.AddPeerError.html\" title=\"enum umsh_mac::AddPeerError\">AddPeerError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Registers or refreshes a known remote peer in the shared registry.</p>\n<p>When the <code>software-crypto</code> feature is enabled, the supplied public key\nis validated as a well-formed Ed25519 compressed point on the curve.\nMalformed keys are rejected with <a href=\"umsh_mac/enum.AddPeerError.html#variant.InvalidPublicKey\" title=\"variant umsh_mac::AddPeerError::InvalidPublicKey\"><code>AddPeerError::InvalidPublicKey</code></a>\nbefore they can pollute the peer registry.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_peer\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1344\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.remove_peer\" class=\"fn\">remove_peer</a>(&amp;mut self, key: &amp;PublicKey) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Removes a registered peer and every piece of per-peer transport state:\npairwise crypto, replay windows, pending counter resyncs, and any\ndeferred inbound frame. Returns whether the peer was registered.</p>\n<p>The peer registry is dense, so removal moves the last entry into the\nfreed slot; state keyed by the moved peer’s old identifier is re-keyed\nhere. Persisted RX counter boundaries are deliberately retained: if\nthe peer is re-added later, replay protection resumes from the stored\nboundary instead of accepting replays from before the removal.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_channel\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1366\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.add_channel\" class=\"fn\">add_channel</a>(&amp;mut self, key: ChannelKey) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"struct\" href=\"umsh_mac/struct.CapacityError.html\" title=\"struct umsh_mac::CapacityError\">CapacityError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Adds or updates a shared channel and derives its multicast keys.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.remove_channel\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1374\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.remove_channel\" class=\"fn\">remove_channel</a>(&amp;mut self, key: &amp;ChannelKey) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Removes a previously added channel by its exact key, discarding\nthe channel’s replay state with it (re-adding the key later\nstarts at first contact). Returns whether a channel was removed.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.add_named_channel\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1382\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.add_named_channel\" class=\"fn\">add_named_channel</a>(&amp;mut self, name: &amp;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.str.html\">str</a>) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/enum.AddChannelError.html\" title=\"enum umsh_mac::AddChannelError\">AddChannelError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Adds or updates a named channel using the coordinator’s channel-key derivation.</p>\n<p>The name is canonicalized (ASCII lowercase fold) before derivation, so\n<code>Public</code> and <code>public</code> register the same channel.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.identity_count\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1392\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.identity_count\" class=\"fn\">identity_count</a>(&amp;self) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a></h4></section></summary><div class=\"docblock\"><p>Return the number of occupied identity slots.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.install_pairwise_keys_advanced\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1443-1448\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.install_pairwise_keys_advanced\" class=\"fn\">install_pairwise_keys_advanced</a>(\n    &amp;mut self,\n    identity_id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer_id: <a class=\"struct\" href=\"umsh_mac/peers/struct.PeerId.html\" title=\"struct umsh_mac::peers::PeerId\">PeerId</a>,\n    pairwise_keys: PairwiseKeys,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/peers/struct.PeerCryptoState.html\" title=\"struct umsh_mac::peers::PeerCryptoState\">PeerCryptoState</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Installs pairwise transport keys for one local identity and remote peer.</p>\n<h5 id=\"safety-logical\"><a class=\"doc-anchor\" href=\"#safety-logical\">§</a>Safety (logical)</h5>\n<p>Installing wrong keys will silently corrupt the session. This method\nis deliberately gated behind the <code>unsafe-advanced</code> feature. Prefer\ngoing through the node-layer PFS session manager instead.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_broadcast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1463-1468\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_broadcast\" class=\"fn\">queue_broadcast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a broadcast frame for transmission.</p>\n<p>Note: the <code>encrypted</code>, <code>ack_requested</code>, and <code>salt</code> flags on <code>options</code>\nare silently forced to <code>false</code> because broadcasts cannot carry any of\nthem on the wire.</p>\n<p>TODO: this sanitization is silent — a caller that explicitly set\n<code>ack_requested = true</code> for a broadcast will get a successful\n<code>SendReceipt</code> and never learn the flag was dropped. Surface this as a\ndebug-level event (or split <code>SendOptions</code> into kind-specific\nbuilders) so the loss is observable.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_broadcast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1535-1540\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.send_broadcast\" class=\"fn\">send_broadcast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a broadcast frame for transmission.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_multicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1545-1551\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_multicast\" class=\"fn\">queue_multicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a multicast frame using the configured channel keys.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_multicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1623-1629\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.send_multicast\" class=\"fn\">send_multicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a multicast frame for transmission.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_mac_ack_for_peer\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1653-1659\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_mac_ack_for_peer\" class=\"fn\">queue_mac_ack_for_peer</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer_id: <a class=\"struct\" href=\"umsh_mac/peers/struct.PeerId.html\" title=\"struct umsh_mac::peers::PeerId\">PeerId</a>,\n    ack_trailer: [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>],\n    trace_route: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a MAC ACK frame, using any cached route to <code>peer_id</code> when available.</p>\n<p><code>trace_route</code> mirrors the acknowledged frame: a sender that attached a\ntrace route was discovering a path, and the trace it collected only\ntaught <em>us</em> the way back. The matching trace on this ack is what closes\nthe other direction, and is the only thing an ack-only exchange gives\nthe sender to learn a route from.</p>\n<p>It is honored only when the route attached below gives this ack some\nway to be repeated. An ack going back to a peer we hear directly\ncarries neither a flood budget nor a source route, so no repeater may\ntouch it and the trace would arrive as empty as it left. The sender\nreads the direct link off the ack’s own shape instead — see\n[<code>Coordinator::learn_route_for_peer</code>].</p>\n<p>An ack that does ride through repeaters is tracked like any other\nrepeat-confirmed send: silence where the repeat should be means the\nfirst hop never got it, and the retry ladder retransmits. The ladder\nends in a silent abandon — the sender’s own data retries are the\nbackstop; this just spares them in the common case.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_mac_ack\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1757\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_mac_ack\" class=\"fn\">queue_mac_ack</a>(&amp;mut self, ack_trailer: [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>]) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues an immediate direct MAC ACK frame.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_unicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1770-1776\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_unicast\" class=\"fn\">queue_unicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer: &amp;PublicKey,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a unicast frame and optional pending-ACK state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_unicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1888-1894\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.send_unicast\" class=\"fn\">send_unicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer: &amp;PublicKey,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a unicast frame for transmission, deriving secure peer state on first use.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.queue_blind_unicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#1904-1911\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.queue_blind_unicast\" class=\"fn\">queue_blind_unicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer: &amp;PublicKey,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueues a blind-unicast frame and optional pending-ACK state.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.send_blind_unicast\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2052-2059\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.send_blind_unicast\" class=\"fn\">send_blind_unicast</a>(\n    &amp;mut self,\n    from: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    peer: &amp;PublicKey,\n    channel_id: &amp;ChannelId,\n    payload: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>],\n    options: &amp;<a class=\"struct\" href=\"umsh_mac/send/struct.SendOptions.html\" title=\"struct umsh_mac::send::SendOptions\">SendOptions</a>,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.SendError.html\" title=\"enum umsh_mac::coordinator::SendError\">SendError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Enqueue a blind-unicast frame for transmission, deriving secure peer state on first use.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.transmit_next\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2100-2103\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.transmit_next\" class=\"fn\">transmit_next</a>(\n    &amp;mut self,\n    on_event: &amp;mut impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>&gt;, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Transmit the next eligible queued frame, if any.</p>\n<p>While a post-transmit forwarding listen window is active, only immediate MAC\nACK traffic is permitted to bypass the listen state. Forwarded sends arm a new\nlisten window after the radio transmit completes. Non-immediate traffic honors\nqueued CAD backoff state and gives up after the configured maximum number of\nCAD attempts.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.drain_tx_queue\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2247-2250\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.drain_tx_queue\" class=\"fn\">drain_tx_queue</a>(\n    &amp;mut self,\n    on_event: &amp;mut impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Keep transmitting until the queue is empty.</p>\n<p>Progress stops when CAD keeps reporting busy, when a post-transmit listen window blocks\nnormal traffic, or when the queue is otherwise unable to shrink further in the current cycle.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_cycle\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2273-2276\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.poll_cycle\" class=\"fn\">poll_cycle</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Runs one coordinator cycle over the current MAC state.</p>\n<p>The cycle performs four ordered phases:</p>\n<ol>\n<li>Drain any queued transmit work.</li>\n<li>Receive and process at most one inbound frame.</li>\n<li>Drain any immediate ACK generated during receive handling.</li>\n<li>Service pending ACK timers and emit timeout events.</li>\n</ol>\n<p>The callback may be invoked zero or more times depending on what the\nreceive and timeout phases accept or resolve.\nService one MAC coordinator cycle.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.earliest_deadline_ms\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2295\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.earliest_deadline_ms\" class=\"fn\">earliest_deadline_ms</a>(&amp;self) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u64.html\">u64</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Compute the earliest deadline across all coordinator timers.</p>\n<p>Returns <code>None</code> when there are no pending timers.  The returned value\ncovers pending ACK deadlines (both <code>ack_deadline_ms</code> and forwarding\n<code>confirm_deadline_ms</code>), the post-transmit listen window, and deferred\ntransmit-queue entries.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.next_event\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2351-2354\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.next_event\" class=\"fn\">next_event</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Run the coordinator’s event loop until at least one event is delivered\nor a timer-driven action (retransmit, timeout) is processed.</p>\n<p>Unlike <a href=\"umsh_mac/coordinator/struct.Mac.html#method.poll_cycle\" title=\"method umsh_mac::coordinator::Mac::poll_cycle\"><code>poll_cycle</code></a>, this method properly awaits the\nradio and timer deadlines instead of returning immediately when nothing\nis ready.  Callers can use <code>tokio::select!</code> (or equivalent) to multiplex\nuser input alongside MAC events:</p>\n\n<div class=\"example-wrap ignore\"><a href=\"#\" class=\"tooltip\" title=\"This example is not tested\">ⓘ</a><pre class=\"rust rust-example-rendered\"><code><span class=\"kw\">loop </span>{\n    <span class=\"macro\">tokio::select!</span> {\n        line = stdin.next_line() =&gt; { <span class=\"comment\">/* handle input */ </span>}\n        result = mac.next_event(|id, event| { <span class=\"comment\">/* handle event */ </span>}) =&gt; {\n            result<span class=\"question-mark\">?</span>;\n        }\n    }\n}</code></pre></div></div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.poll_wait_for_wake\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2392-2396\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.poll_wait_for_wake\" class=\"fn\">poll_wait_for_wake</a>(\n    &amp;mut self,\n    cx: &amp;mut <a class=\"struct\" href=\"https://doc.rust-lang.org/nightly/core/task/wake/struct.Context.html\" title=\"struct core::task::wake::Context\">Context</a>&lt;'_&gt;,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/task/poll/enum.Poll.html\" title=\"enum core::task::poll::Poll\">Poll</a>&lt;<a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"enum\" href=\"umsh_mac/coordinator/enum.WakeReason.html\" title=\"enum umsh_mac::coordinator::WakeReason\">WakeReason</a>, &lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Register radio/timer wakers and report what has become ready.</p>\n<p>This is Phase 2 of <a href=\"umsh_mac/coordinator/struct.Mac.html#method.next_event\" title=\"method umsh_mac::coordinator::Mac::next_event\"><code>next_event</code></a> exposed as a sync\npoll method so that callers sharing the coordinator through an\n<code>AsyncRefCell</code> can release the exclusive borrow between polls. The\ncaller-provided <code>buf</code> is populated with the received frame when the\nreturn value is <a href=\"umsh_mac/coordinator/enum.WakeReason.html#variant.Received\" title=\"variant umsh_mac::coordinator::WakeReason::Received\"><code>WakeReason::Received</code></a>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.process_wake_reason\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2452-2457\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.process_wake_reason\" class=\"fn\">process_wake_reason</a>(\n    &amp;mut self,\n    reason: <a class=\"enum\" href=\"umsh_mac/coordinator/enum.WakeReason.html\" title=\"enum umsh_mac::coordinator::WakeReason\">WakeReason</a>,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Run Phases 3-5 after <a href=\"umsh_mac/coordinator/struct.Mac.html#method.poll_wait_for_wake\" title=\"method umsh_mac::coordinator::Mac::poll_wait_for_wake\"><code>poll_wait_for_wake</code></a>\nhas reported a wake reason: process the received frame (if any),\ndrain immediate ACKs, and service pending ACK timeouts.</p>\n<h5 id=\"precondition\"><a class=\"doc-anchor\" href=\"#precondition\">§</a>Precondition</h5>\n<p>When <code>reason</code> is <a href=\"umsh_mac/coordinator/enum.WakeReason.html#variant.Received\" title=\"variant umsh_mac::coordinator::WakeReason::Received\"><code>WakeReason::Received</code></a>, <code>buf</code> <strong>must</strong> be the same\nbuffer — containing the same bytes — that was passed to the matching\n<a href=\"umsh_mac/coordinator/struct.Mac.html#method.poll_wait_for_wake\" title=\"method umsh_mac::coordinator::Mac::poll_wait_for_wake\"><code>poll_wait_for_wake</code></a> call. The received\nframe bytes live in <code>buf[..rx.len]</code>; <code>reason</code> only carries the\naccompanying metadata (<code>RxInfo</code>). Passing a different or reinitialized\nbuffer will cause the received frame to be silently discarded and the\ncontents of <code>buf</code> to be misinterpreted as a MAC frame.</p>\n<p>This precondition only matters when using the split-phase API for\n<a href=\"umsh_sync::AsyncRefCell\"><code>AsyncRefCell</code></a> sharing. When driving the\ncoordinator through <a href=\"umsh_mac/coordinator/struct.Mac.html#method.next_event\" title=\"method umsh_mac::coordinator::Mac::next_event\"><code>next_event</code></a> the buffer is a\nlocal stack variable and the pairing is guaranteed automatically.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.run\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2483-2486\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.run\" class=\"fn\">run</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Drive the coordinator forever, invoking <code>on_event</code> for each delivered event.</p>\n<p>This is the preferred long-lived run loop for standalone MAC-driven tasks such as\nrepeaters or dedicated radio services. Unlike manually calling\n<a href=\"umsh_mac/coordinator/struct.Mac.html#method.poll_cycle\" title=\"method umsh_mac::coordinator::Mac::poll_cycle\"><code>poll_cycle</code></a> in a loop, <code>run</code> keeps the wake/sleep policy inside\nthe coordinator by delegating to <a href=\"umsh_mac/coordinator/struct.Mac.html#method.next_event\" title=\"method umsh_mac::coordinator::Mac::next_event\"><code>next_event</code></a>, which already\nwaits for radio activity and protocol deadlines.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.run_quiet\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2497\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.run_quiet\" class=\"fn\">run_quiet</a>(\n    &amp;mut self,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Drive the coordinator forever while ignoring emitted events.</p>\n<p>Useful for standalone repeaters or bridge tasks that do not need to observe inbound\ndeliveries directly but still need the coordinator to service forwarding, ACKs, and\nretransmissions without an app-owned polling loop.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.process_received_frame\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#2510-2516\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.process_received_frame\" class=\"fn\">process_received_frame</a>(\n    &amp;mut self,\n    buf: &amp;mut [<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">FRAME</a>],\n    frame_len: <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.usize.html\">usize</a>,\n    rx: &amp;<a class=\"struct\" href=\"umsh_hal/struct.RxInfo.html\" title=\"struct umsh_hal::RxInfo\">RxInfo</a>,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Process a received frame, dispatching events through <code>on_event</code>.</p>\n<p>This is the shared implementation used by both <a href=\"umsh_mac/coordinator/struct.Mac.html#method.receive_one\" title=\"method umsh_mac::coordinator::Mac::receive_one\"><code>receive_one</code></a>\nand <a href=\"umsh_mac/coordinator/struct.Mac.html#method.next_event\" title=\"method umsh_mac::coordinator::Mac::next_event\"><code>next_event</code></a>.  Returns <code>true</code> when the frame\nproduced at least one event or side-effect.</p>\n<p>Every reception passes through here exactly once, which is what\nmakes it the place to tally them: the <code>rx_frames</code>/<code>rx_accepted</code>\npair counts one radio reception and whether anything came of it.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.receive_one\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#3252-3255\">Source</a><h4 class=\"code-header\">pub async fn <a href=\"#method.receive_one\" class=\"fn\">receive_one</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a>, <a class=\"enum\" href=\"umsh_mac/coordinator/enum.MacError.html\" title=\"enum umsh_mac::coordinator::MacError\">MacError</a>&lt;&lt;&lt;P as <a class=\"trait\" href=\"umsh_mac/trait.Platform.html\" title=\"trait umsh_mac::Platform\">Platform</a>&gt;::<a class=\"associatedtype\" href=\"umsh_mac/trait.Platform.html#associatedtype.Radio\" title=\"type umsh_mac::Platform::Radio\">Radio</a> as <a class=\"trait\" href=\"umsh_hal/trait.Radio.html\" title=\"trait umsh_hal::Radio\">Radio</a>&gt;::<a class=\"associatedtype\" href=\"umsh_hal/trait.Radio.html#associatedtype.Error\" title=\"type umsh_hal::Radio::Error\">Error</a>&gt;&gt;</h4></section></summary><div class=\"docblock\"><p>Non-blocking receive: polls the radio once and processes a frame if available.</p>\n<p>This is the legacy non-blocking API used by <a href=\"umsh_mac/coordinator/struct.Mac.html#method.poll_cycle\" title=\"method umsh_mac::coordinator::Mac::poll_cycle\"><code>poll_cycle</code></a>.\nFor new code, prefer <a href=\"umsh_mac/coordinator/struct.Mac.html#method.next_event\" title=\"method umsh_mac::coordinator::Mac::next_event\"><code>next_event</code></a> which properly awaits\nthe radio and timer deadlines.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.complete_ack\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#3275-3279\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.complete_ack\" class=\"fn\">complete_ack</a>(\n    &amp;mut self,\n    peer: &amp;PublicKey,\n    ack_trailer: &amp;[<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.u8.html\">u8</a>; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.array.html\">8</a>],\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/option/enum.Option.html\" title=\"enum core::option::Option\">Option</a>&lt;(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>)&gt;</h4></section></summary><div class=\"docblock\"><p>Mark a pending receipt as acknowledged and emit an event through <code>on_event</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.service_pending_ack_timeouts\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#3317-3320\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.service_pending_ack_timeouts\" class=\"fn\">service_pending_ack_timeouts</a>(\n    &amp;mut self,\n    on_event: impl <a class=\"trait\" href=\"https://doc.rust-lang.org/nightly/core/ops/function/trait.FnMut.html\" title=\"trait core::ops::function::FnMut\">FnMut</a>(<a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>, <a class=\"enum\" href=\"umsh_mac/send/enum.MacEventRef.html\" title=\"enum umsh_mac::send::MacEventRef\">MacEventRef</a>&lt;'_&gt;),\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.unit.html\">()</a>, <a class=\"struct\" href=\"umsh_mac/struct.CapacityError.html\" title=\"struct umsh_mac::CapacityError\">CapacityError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Expire or retry pending ACK state based on <code>now_ms</code>.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.cancel_pending_ack\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#3521-3525\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.cancel_pending_ack\" class=\"fn\">cancel_pending_ack</a>(\n    &amp;mut self,\n    identity_id: <a class=\"struct\" href=\"umsh_mac/coordinator/struct.LocalIdentityId.html\" title=\"struct umsh_mac::coordinator::LocalIdentityId\">LocalIdentityId</a>,\n    receipt: <a class=\"struct\" href=\"umsh_mac/send/struct.SendReceipt.html\" title=\"struct umsh_mac::send::SendReceipt\">SendReceipt</a>,\n) -&gt; <a class=\"primitive\" href=\"https://doc.rust-lang.org/nightly/std/primitive.bool.html\">bool</a></h4></section></summary><div class=\"docblock\"><p>Cancel a pending ACK-requested send, stopping retransmissions.</p>\n<p>Removes the pending ACK entry for the given identity slot and receipt,\nand removes any matching entry from the transmit queue. Returns <code>true</code>\nif a pending ACK was found and removed.</p>\n</div></details><details class=\"toggle method-toggle\" open><summary><section id=\"method.ensure_transient_peer\" class=\"method\"><a class=\"src rightside\" href=\"src/umsh_mac/coordinator.rs.html#4329\">Source</a><h4 class=\"code-header\">pub fn <a href=\"#method.ensure_transient_peer\" class=\"fn\">ensure_transient_peer</a>(\n    &amp;mut self,\n    key: &amp;PublicKey,\n) -&gt; <a class=\"enum\" href=\"https://doc.rust-lang.org/nightly/core/result/enum.Result.html\" title=\"enum core::result::Result\">Result</a>&lt;<a class=\"struct\" href=\"umsh_mac/peers/struct.PeerId.html\" title=\"struct umsh_mac::peers::PeerId\">PeerId</a>, <a class=\"enum\" href=\"umsh_mac/enum.AddPeerError.html\" title=\"enum umsh_mac::AddPeerError\">AddPeerError</a>&gt;</h4></section></summary><div class=\"docblock\"><p>Ensure <code>key</code> is registered at least transiently, returning its slot.</p>\n<p>A known peer is returned as-is; an unknown one is auto-registered\nexactly like a full-source sender would be — unpinned and\nLRU-evictable, never promoted. This is the node layer’s hook for\nanswering a stranger (an Identity Request reply, say) whose frame\narrived on a path that does not auto-register its source, such as a\nbroadcast. Deliberately not gated on\n<a href=\"umsh_mac/coordinator/struct.Mac.html#method.auto_register_full_key_peers\" title=\"method umsh_mac::coordinator::Mac::auto_register_full_key_peers\"><code>auto_register_full_key_peers</code></a>:\nthe caller is making an explicit per-peer decision, not opting into\nregistering every full-source sender.</p>\n</div></details></div></details>",0,"umshctl::command::manage::CtlMac"]]]]);
    if (window.register_type_impls) {
        window.register_type_impls(type_impls);
    } else {
        window.pending_type_impls = type_impls;
    }
})()
